package e.e.a;
import android.graphics.*;import android.os.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,34,36},manifest=Config.NONE)
public class NicoliveEfficiencyTest {
 static class Browser extends NicoliveBrowser {AtomicInteger feedsRead=new AtomicInteger(),imagesRead=new AtomicInteger();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);boolean block;byte[] png;
  @Override byte[] bytes(String url,String cookie,int max,boolean feed)throws java.io.IOException {if(feed)feedsRead.incrementAndGet();else imagesRead.incrementAndGet();entered.countDown();if(block)try{release.await(5,TimeUnit.SECONDS);}catch(InterruptedException e){throw new java.io.IOException(e);}return feed?url.getBytes(java.nio.charset.StandardCharsets.UTF_8):png;}
 }
 NicoliveBrowser.Result result(final AtomicInteger done){return new NicoliveBrowser.Result(){public void done(String html){done.incrementAndGet();}public void error(){fail("unexpected fetch error");}};}
 void drain(NicoliveBrowser b)throws Exception{if(b.loading!=null)b.loading.get(5,TimeUnit.SECONDS);Shadows.shadowOf(Looper.getMainLooper()).idle();}
 @Test public void hundredSameFeedLoadsUseOneRequestAndRefreshAndAccountChangesRefetch()throws Exception{Browser b=new Browser();try{AtomicInteger done=new AtomicInteger();for(int i=0;i<100;i++){b.load("https://live.nicovideo.jp/","account-a",result(done));drain(b);}assertEquals(100,done.get());assertEquals(1,b.feedsRead.get());b.refresh();b.load("https://live.nicovideo.jp/","account-a",result(done));drain(b);assertEquals(2,b.feedsRead.get());b.load("https://live.nicovideo.jp/","account-b",result(done));drain(b);assertEquals(3,b.feedsRead.get());assertTrue(b.feeds.size()<=3);}finally{b.close();}}
 @Test public void thumbnailDuplicateViewsShareOneFetchAndPausedQueueIsEmpty()throws Exception{Browser b=new Browser();try{Bitmap bitmap=Bitmap.createBitmap(32,18,Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);bitmap.recycle();b.png=out.toByteArray();b.block=true;String url="https://nimg.jp/efficiency-"+System.nanoTime();ImageView[] views=new ImageView[12];for(int i=0;i<views.length;i++){views[i]=new ImageView(org.robolectric.RuntimeEnvironment.getApplication());b.image(url,views[i]);}assertTrue(b.entered.await(5,TimeUnit.SECONDS));assertEquals(1,b.imagesRead.get());assertEquals(1,b.pending.size());b.release.countDown();b.imageWork.shutdown();assertTrue(b.imageWork.awaitTermination(5,TimeUnit.SECONDS));Shadows.shadowOf(Looper.getMainLooper()).idle();for(ImageView v:views)assertTrue(v.getDrawable() instanceof android.graphics.drawable.BitmapDrawable);assertTrue(b.pending.isEmpty());b.pauseImages();assertTrue(((ThreadPoolExecutor)b.imageWork).getQueue().isEmpty());assertTrue(b.work.getQueue().isEmpty());assertTrue(b.images.maxSize()<=8*1024*1024);}finally{b.close();}}
 @Test public void burstLoadsKeepAtMostOnePendingFeedAndOnlyLatestCallback()throws Exception{Browser b=new Browser();try{b.block=true;AtomicInteger done=new AtomicInteger();b.load("https://live.nicovideo.jp/0","",result(done));assertTrue(b.entered.await(5,TimeUnit.SECONDS));for(int i=1;i<200;i++){b.load("https://live.nicovideo.jp/"+i,"",result(done));assertTrue(b.work.getQueue().size()<=1);}b.release.countDown();b.work.shutdown();assertTrue(b.work.awaitTermination(5,TimeUnit.SECONDS));Shadows.shadowOf(Looper.getMainLooper()).idle();assertEquals(1,done.get());assertEquals(1,b.feeds.size());assertTrue(b.feeds.keySet().iterator().next().contains("/199"));}finally{b.close();}}
}
